import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        Arrays.sort(a);
        // the maximum is the single peak; every smaller value can appear once per side
        long answer = 1;
        for (int i = 0; i < n;) {
            int j = i;
            while (j < n && a[j] == a[i]) j++;
            if (a[i] != a[n - 1]) answer += Math.min(j - i, 2);
            i = j;
        }
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"sort"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	a := make([]int64, n)
	for i := range a {
		a[i] = nextInt()
	}
	sort.Slice(a, func(i, j int) bool { return a[i] < a[j] })
	// the maximum is the single peak; every smaller value can appear once per side
	answer := 1
	for i := 0; i < n; {
		j := i
		for j < n && a[j] == a[i] {
			j++
		}
		if a[i] != a[n-1] {
			answer += min(j-i, 2)
		}
		i = j
	}
	fmt.Println(answer)
}
